/// Keeps audit_log rows in the database, through SQLKit: on the database of the unit of work, or on its transaction.
public class SqlAuditLogRepository: @unchecked Sendable {
    private let db: Db?

    public init(db: Db?) {
        self.db = db
    }

    /// The database; the in-memory subclass never asks for it.
    private var database: Db { db! }

    /// At most limit rows from offset, by primary key, and how many there are.
    public func list(offset: Int, limit: Int) async throws -> Page<AuditLog> {
        let total = try await database.sql.raw("SELECT COUNT(*) AS total FROM `audit_log`").first()?.decode(column: "total", as: Int.self) ?? 0
        let items = try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM `audit_log` ORDER BY `at`, `message` LIMIT \(bind: limit) OFFSET \(bind: offset)").all().map(toEntity)
        return Page(items: items, total: total, offset: offset, limit: limit)
    }
}

/// The columns every read selects.
fileprivate let columns = "`at`, `message`"

fileprivate func toEntity(_ row: any SQLRow) throws -> AuditLog {
    AuditLog(
        at: try row.optional("at", as: Date.self),
        message: try row.optional("message", as: String.self)
    )
}

/// Keeps audit_log rows in memory, for tests and for trying the services without a database.
public final class MemoryAuditLogRepository: SqlAuditLogRepository, @unchecked Sendable {
    private let rows = MemoryRows<AuditLog>()

    public init() {
        super.init(db: nil)
    }

    /// The rows reads see, by primary key.
    private func visible() async -> [AuditLog] {
        await rows.all.sorted(by: isBefore)
    }

    override public func list(offset: Int, limit: Int) async throws -> Page<AuditLog> {
        let rows = await visible()
        return Page(items: Array(rows.dropFirst(offset).prefix(limit)), total: rows.count, offset: offset, limit: limit)
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: AuditLog, _ b: AuditLog) -> Bool {
    a.at == b.at && a.message == b.message
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: AuditLog, _ b: AuditLog) -> Bool {
    if a.at != b.at { return less(a.at, b.at) }
    return less(a.message, b.message)
}

