/// Keeps categories rows in the database, through SQLKit: on the database of the unit of work, or on its transaction.
public class SqlCategoryRepository: @unchecked Sendable {
    private let db: Db?

    public init(db: Db?) {
        self.db = db
    }

    /// The database; the in-memory subclass never asks for it.
    private var database: Db { db! }

    /// The row with this primary key, or nil.
    public func getById(_ id: Int) async throws -> Category? {
        try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM `categories` WHERE `id` = \(bind: id)").first().map(toEntity)
    }

    /// At most limit rows from offset, by primary key, and how many there are.
    public func list(offset: Int, limit: Int) async throws -> Page<Category> {
        let total = try await database.sql.raw("SELECT COUNT(*) AS total FROM `categories`").first()?.decode(column: "total", as: Int.self) ?? 0
        let items = try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM `categories` ORDER BY `id` LIMIT \(bind: limit) OFFSET \(bind: offset)").all().map(toEntity)
        return Page(items: items, total: total, offset: offset, limit: limit)
    }

    /// The row with this name, or nil.
    public func getByName(_ name: String) async throws -> Category? {
        try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM `categories` WHERE `name` = \(bind: name)").first().map(toEntity)
    }

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    public func insert(_ entity: Category) async throws -> Category {
        var entity = entity
        var names: [String] = []
        var values: [any SQLExpression] = []
        if let value = entity.id { names.append("`id`"); values.append(SQLQueryString("\(bind: value)")) }
        if let value = entity.name { names.append("`name`"); values.append(SQLQueryString("\(bind: value)")) }
        let insert: SQLQueryString =
            names.isEmpty ? "INSERT INTO `categories` () VALUES ()"
            : "INSERT INTO `categories` (\(unsafeRaw: names.joined(separator: ", "))) VALUES (\(SQLList(values)))"
        let id = try await write { try await database.insert(insert) }
        entity.id = entity.id ?? id
        return try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM `categories` WHERE `id` = \(bind: entity.id!)").first().map(toEntity) ?? entity
    }

    /// Stores the changes made to a row.
    @discardableResult
    public func update(_ entity: Category) async throws -> Category {
        try await write { try await database.sql.raw("UPDATE `categories` SET `name` = \(bound(entity.name)) WHERE `id` = \(bind: entity.id!)").run() }
        return try await database.sql.raw("SELECT \(unsafeRaw: columns) FROM `categories` WHERE `id` = \(bind: entity.id!)").first().map(toEntity) ?? entity
    }

    /// Removes a row.
    public func delete(_ entity: Category) async throws {
        try await write { try await database.sql.raw("DELETE FROM `categories` WHERE `id` = \(bind: entity.id!)").run() }
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error where isRefusal(error) {
            throw DomainError.conflict(entity: "Category", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

/// The columns every read selects.
fileprivate let columns = "`id`, `name`"

fileprivate func toEntity(_ row: any SQLRow) throws -> Category {
    Category(
        id: try row.optional("id", as: Int.self),
        name: try row.optional("name", as: String.self)
    )
}

/// Keeps categories rows in memory, for tests and for trying the services without a database.
public final class MemoryCategoryRepository: SqlCategoryRepository, @unchecked Sendable {
    private let rows = MemoryRows<Category>()

    public init() {
        super.init(db: nil)
    }

    /// The rows reads see, by primary key.
    private func visible() async -> [Category] {
        await rows.all.sorted(by: isBefore)
    }

    override public func getById(_ id: Int) async throws -> Category? {
        await visible().first { $0.id == id }
    }

    override public func list(offset: Int, limit: Int) async throws -> Page<Category> {
        let rows = await visible()
        return Page(items: Array(rows.dropFirst(offset).prefix(limit)), total: rows.count, offset: offset, limit: limit)
    }

    override public func getByName(_ name: String) async throws -> Category? {
        await visible().first { $0.name == name }
    }

    @discardableResult
    override public func insert(_ entity: Category) async throws -> Category {
        var entity = entity
        if entity.id == nil { entity.id = await rows.nextId() }
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    @discardableResult
    override public func update(_ entity: Category) async throws -> Category {
        await rows.store(entity) { sameKey($0, entity) }
        return entity
    }

    override public func delete(_ entity: Category) async throws {
        await rows.remove { sameKey($0, entity) }
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: Category, _ b: Category) -> Bool {
    a.id == b.id
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: Category, _ b: Category) -> Bool {
    return less(a.id, b.id)
}

