/// Keeps tags rows in memory, for tests and for trying the services without a database.
public final class MemoryTagRepository: SqlTagRepository, @unchecked Sendable {
    private let rows = MemoryRows<Tag>()

    public init() {
        super.init(db: nil)
    }

    /// The rows reads see, by primary key.
    private func visible() async -> [Tag] {
        await rows.all.sorted(by: isBefore)
    }

    override public func getById(_ id: Int) async throws -> Tag? {
        await visible().first { $0.id == id }
    }

    override public func list(offset: Int, limit: Int) async throws -> Page<Tag> {
        let rows = await visible()
        return Page(items: Array(rows.dropFirst(offset).prefix(limit)), total: rows.count, offset: offset, limit: limit)
    }

    @discardableResult
    override public func insert(_ entity: Tag) async throws -> Tag {
        var entity = entity
        if entity.id == nil { entity.id = await rows.nextId() }
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    @discardableResult
    override public func update(_ entity: Tag) async throws -> Tag {
        await rows.store(entity) { sameKey($0, entity) }
        return entity
    }

    override public func delete(_ entity: Tag) async throws {
        await rows.remove { sameKey($0, entity) }
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: Tag, _ b: Tag) -> Bool {
    a.id == b.id
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: Tag, _ b: Tag) -> Bool {
    return less(a.id, b.id)
}

