/// What services depend on: a repository per table and a transaction. Every repository write is committed at once; transaction() only groups the code.
public protocol UnitOfWork: Sendable {
    var customers: SqlCustomerRepository { get }
    var categories: SqlCategoryRepository { get }
    var products: SqlProductRepository { get }
    var orders: SqlOrderRepository { get }
    var orderLines: SqlOrderLineRepository { get }
    var tags: SqlTagRepository { get }
    var productTags: SqlProductTagRepository { get }
    var auditLog: SqlAuditLogRepository { get }

    /// Runs work with the repositories of the transaction; commits when it ends, rolls back when it throws.
    func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T
}

/// The repositories over one database, and its transaction.
public struct SqlUnitOfWork: UnitOfWork {
    public let db: Db

    public init(db: Db) {
        self.db = db
    }

    public var customers: SqlCustomerRepository { SqlCustomerRepository(db: db) }

    public var categories: SqlCategoryRepository { SqlCategoryRepository(db: db) }

    public var products: SqlProductRepository { SqlProductRepository(db: db) }

    public var orders: SqlOrderRepository { SqlOrderRepository(db: db) }

    public var orderLines: SqlOrderLineRepository { SqlOrderLineRepository(db: db) }

    public var tags: SqlTagRepository { SqlTagRepository(db: db) }

    public var productTags: SqlProductTagRepository { SqlProductTagRepository(db: db) }

    public var auditLog: SqlAuditLogRepository { SqlAuditLogRepository(db: db) }

    /// Every write is committed at once: this only groups the code.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await work(self)
    }
}

/// The in-memory repositories, for tests and for trying the services without a database.
public final class MemoryUnitOfWork: UnitOfWork {
    public let customers: SqlCustomerRepository = MemoryCustomerRepository()
    public let categories: SqlCategoryRepository = MemoryCategoryRepository()
    public let products: SqlProductRepository = MemoryProductRepository()
    public let orders: SqlOrderRepository = MemoryOrderRepository()
    public let orderLines: SqlOrderLineRepository = MemoryOrderLineRepository()
    public let tags: SqlTagRepository = MemoryTagRepository()
    public let productTags: SqlProductTagRepository = MemoryProductTagRepository()
    public let auditLog: SqlAuditLogRepository = MemoryAuditLogRepository()

    public init() {}

    /// Memory has no transactions: changes are kept as they are made.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await work(self)
    }
}

